mapper.select:
SELECT p.product_id, p.category_id, c.category_name, p.name, p.author, p.publisher, p.price, p.stock_quantity, pi.image_path FROM product p LEFT JOIN category c ON p.category_id = c.category_id LEFT JOIN product_image pi ON p.product_id = pi.product_id AND pi.image_type = 'THUMBNAIL' WHERE p.deleted_at IS NULL AND p.status = 'ACTIVE'
AND p.category_id = #{categoryId}
AND ( p.name LIKE CONCAT('%', #{keyword}, '%') OR p.author LIKE CONCAT('%', #{keyword}, '%') OR p.publisher LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY p.created_at DESC LIMIT #{size} OFFSET #{offset}

