AND p.category_id = #{categoryId}
AND ( p.name LIKE CONCAT('%', #{keyword}, '%') OR p.author LIKE CONCAT('%', #{keyword}, '%') OR p.publisher LIKE CONCAT('%', #{keyword}, '%') )
